using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};
static double[] N(object x){return ((Array)x).Cast<object>().Select(Convert.ToDouble).ToArray();}
static object Params(IZParameterMgr m){var rows=new List<object>();for(int i=0;i<m.Count;i++){var p=m.GetParameter(i);rows.Add(new{name=p.Name,expression=p.Expression,notes=p.Notes});}return rows;}
static double[] M(IZSceneElement e){var m=e.GetTransformToGlobal();return Enumerable.Range(0,16).Select(k=>m.GetValue(k/4,k%4)).ToArray();}
static object Outline(IZProfile p){var result=new List<object>();foreach(object raw in (Array)p.GetCurveIds()){int id=Convert.ToInt32(raw);string kind=p.GetCurveType(id).ToString();object a,b;double radius;if(kind=="Z_CURVE2D_LINE"){p.GetLineData(id,out a,out b);result.Add(new{kind=kind,a=N(a),b=N(b)});}else if(kind=="Z_CURVE2D_CIRCLE"){p.GetCircleData(id,out a,out radius);result.Add(new{kind=kind,center=N(a),radius=radius});}else result.Add(new{kind=kind});}return result;} static object Center(IZProfile p){var pts=new List<double[]>();foreach(object raw in (Array)p.GetCurveIds()){int id=Convert.ToInt32(raw);var kind=p.GetCurveType(id).ToString();object a,b;double radius;
 if(kind=="Z_CURVE2D_LINE"){p.GetLineData(id,out a,out b);pts.Add(N(a));pts.Add(N(b));}
 else if(kind=="Z_CURVE2D_CIRCLE"){p.GetCircleData(id,out a,out radius);var c=N(a);pts.Add(new[]{c[0]-radius,c[1]-radius});pts.Add(new[]{c[0]+radius,c[1]+radius});}}
 if(pts.Count==0)return null;double[] center={(pts.Min(v=>v[0])+pts.Max(v=>v[0]))/2,(pts.Min(v=>v[1])+pts.Max(v=>v[1]))/2,0};var m=((IZSceneElement)p).GetTransformToGlobal();return Enumerable.Range(0,3).Select(j=>1000*(m.GetValue(3,j)+Enumerable.Range(0,3).Sum(k=>center[k]*m.GetValue(k,j)))).ToArray();}
public static int Run(string folder){var result=new Dictionary<string,object>();bool pass=false;try{var q=(Dictionary<string,object>)J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong host");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");
 var docs=((Array)app.GetAllOpenDocs()).Cast<object>().Select(x=>x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x))));var doc=docs.Single(d=>d.FileGUID==(string)q["guid"]);var s=(IZSceneDoc)doc;var u=(IZSceneDocUtility)s;var rows=new List<object>();
 foreach(object raw in (object[])q["ids"]){var e=u.GetElementById(Convert.ToInt32(raw));var p=(IZPart)e;var fs=new List<object>();var fm=(IZPartFeatureMgr)p;
 for(int i=0;i<fm.GetFeaturesCount();i++)try{var f=fm.GetFeatureAt(i);var se=(IZSceneElement)f;var fr=new Dictionary<string,object>{{"id",((IZElement)f).Id},{"parameters",Params(se.ParameterMgr)},{"world_matrix_m",M(se)},{"position_expressions",Enumerable.Range(0,3).Select(k=>se.get_PositionTransformComponentExpression((eZTransformComponentType)k)).ToArray()}};var ex=f as IZExtrudeFeature;if(ex!=null){fr["profile_center_world_mm"]=Center(ex.CrossSection);fr["outline"]=Outline(ex.CrossSection);fr["local_matrix_m"]=Enumerable.Range(0,16).Select(k=>se.GetTransformToParent().GetValue(k/4,k%4)).ToArray();}fs.Add(fr);}catch(COMException error){fs.Add(new{index=i,error=error.Message});}
 var box=(IZSizeBox)p;var pe=(IZSceneElement)e;rows.Add(new{id=e.Id,anchor_behavior=pe.AnchorBehavior.ToString(),keep_anchor=box.KeepAnchorFixedInSpace,resize_x=box.LengthResizeBehavior.ToString(),resize_y=box.WidthResizeBehavior.ToString(),resize_z=box.HeightResizeBehavior.ToString(),position_expr=Enumerable.Range(0,3).Select(k=>pe.get_PositionTransformComponentExpression((eZTransformComponentType)k)).ToArray(),parameters=Params(((IZSceneElement)e).ParameterMgr),features=fs});}
 result["rows"]=rows;
 var camera=(IZCamera)s.CameraMgr.ActiveCamera;camera.Perspective=false;camera.Direction=new double[]{.45,.8,-.5};camera.Up=new double[]{0,0,1};s.AdjustCameraToFitShapeInRect(1400,1100);s.Redraw();s.ExportImage(Path.Combine(folder,"original-iso.png"),eZImageFormat.Z_IMAGE_PNG,1400,1100,true);pass=true;
}catch(Exception ex){result["error"]=ex.ToString();}result["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(result));return pass?0:1;}
}}
